// Generated Munsell HVC coordinate approximation; see COLOR-DATA.md.
const bytes=atob("");const grid=new Int16Array(65**3*3);for(let i=0;i<grid.length;i++)grid[i]=bytes.charCodeAt(2*i)|(bytes.charCodeAt(2*i+1)<<8);

export function rgbToMunsell(rgb){
 if(!rgb||rgb.length!==3||!Array.from(rgb).every(Number.isFinite))return null;
 const q=Array.from(rgb).map(x=>Math.max(0,Math.min(255,x))*64/255),lo=q.map(x=>Math.min(63,Math.floor(x))),f=q.map((x,i)=>x-lo[i]),v=[0,0,0];
 for(let r=0;r<2;r++)for(let g=0;g<2;g++)for(let b=0;b<2;b++){
  const weight=(r?f[0]:1-f[0])*(g?f[1]:1-f[1])*(b?f[2]:1-f[2]),index=(((lo[0]+r)*65+lo[1]+g)*65+lo[2]+b)*3;
  for(let i=0;i<3;i++)v[i]+=weight*grid[index+i];
 }
 const u=v[0]/512,w=v[2]/512,neutral=rgb[0]===rgb[1]&&rgb[1]===rgb[2];
 return {h:neutral?0:(Math.atan2(w,u)*50/Math.PI+100)%100,v:v[1]/2048,c:neutral?0:Math.hypot(u,w),approximate:true};
}
